import { motion } from "framer-motion";

export default function Hero() {
  const scrollToSection = (id) => {
    const section = document.getElementById(id);
    if (section) {
      section.scrollIntoView({ behavior: "smooth" });
    }
  };

  return (
    <section className="min-h-screen flex items-center justify-center text-center px-6 pt-20">
      <motion.div
        initial={{ opacity: 0, y: 40 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.9 }}
        className="max-w-4xl"
      >
        <h1 className="text-5xl md:text-6xl font-bold leading-tight">
          Training Built on{" "}
          <span className="text-red-600">Structure</span>, Not Shortcuts
        </h1>

        <p className="mt-6 text-lg text-gray-300">
          Structured training, consistent coaching, and disciplined workout
          environments designed for long-term fitness.
        </p>

        <div className="mt-8 flex justify-center gap-4">
          <button
            onClick={() => scrollToSection("membership")}
            className="px-6 py-3 bg-red-700 hover:bg-red-600 transition rounded red-glow"
          >
            View Membership Plans
          </button>

          <button
            onClick={() => scrollToSection("programs")}
            className="px-6 py-3 border border-red-700 hover:bg-red-700/20 transition rounded"
          >
            Explore Programs
          </button>
        </div>
      </motion.div>
    </section>
  );
}
